[CmdletBinding()]
param([string]$ValidatorPath = (Join-Path (Split-Path -Parent (Split-Path -Parent $PSScriptRoot)) 'validate-wp5.ps1'))

$ErrorActionPreference = 'Stop'
$text = [IO.File]::ReadAllText($ValidatorPath)
$pattern = "(?s)\`$previousPath=Join-Path \`$vroot 'previous-claim-ledger\.json';.*?(?=Req\(-not\(Compare-Object @\(\`$ledger\.sources)"
$replacement = @'
$lineagePath=Join-Path $vroot 'ledger-lineage.json';$lineage=ReadStrictJson $lineagePath @('schema','anchors','migrations') ledger_lineage;Req($lineage.schema-ceq'wp5-ledger-lineage-v1'-and-not(Compare-Object @($lineage.anchors.PSObject.Properties.Name) @('loop27','loop28','loop29'))-and-not(Compare-Object @($lineage.migrations.PSObject.Properties.Name) @('loop28','loop29')))'ledger lineage schema'
foreach($name in @('loop27','loop28','loop29')){$a=$lineage.anchors.$name;Req(-not(Compare-Object @($a.PSObject.Properties.Name) @('path','sha256','active_count','tombstone_count'))-and$a.path-notmatch'[\\/]' -and$a.sha256-cmatch'^[0-9a-f]{64}$')"ledger lineage anchor $name"}
foreach($name in @('loop28','loop29')){$m=$lineage.migrations.$name;Req(-not(Compare-Object @($m.PSObject.Properties.Name) @('from','to','path','sha256','replacements','tombstones'))-and$m.from-ceq('loop'+([int]$name.Substring(4)-1))-and$m.to-ceq$name-and$m.path-notmatch'[\\/]' -and$m.sha256-cmatch'^[0-9a-f]{64}$')"ledger lineage migration $name"}
function ReadLedgerAnchor($name){$a=$lineage.anchors.$name;$p=Join-Path $vroot $a.path;Req((Test-Path -LiteralPath $p)-and(Get-FileHash -Algorithm SHA256 $p).Hash.ToLowerInvariant()-ceq$a.sha256)"ledger lineage anchor hash $name";$x=ReadStrictJson $p @('schema','previous_ledger_sha256','tombstones','counts','sources','entries') "ledger_$name";Req($x.schema-ceq'wp5-claim-ledger-v1'-and@($x.entries).Count-eq[int]$a.active_count-and@($x.tombstones).Count-eq[int]$a.tombstone_count-and(@($x.entries).Count+@($x.tombstones).Count)-eq1048)"ledger lineage anchor count $name";$x}
$loop27=ReadLedgerAnchor 'loop27';$loop28=ReadLedgerAnchor 'loop28';Req((Get-FileHash -Algorithm SHA256 (Join-Path $vroot 'previous-claim-ledger.json')).Hash.ToLowerInvariant()-ceq$lineage.anchors.loop27.sha256)'loop27 legacy anchor';Req((Get-FileHash -Algorithm SHA256 (Join-Path $vroot 'claim-ledger.json')).Hash.ToLowerInvariant()-ceq$lineage.anchors.loop29.sha256)'loop29 current ledger anchor';Req($ledger.previous_ledger_sha256-ceq$lineage.anchors.loop28.sha256-and$loop28.previous_ledger_sha256-ceq$lineage.anchors.loop27.sha256)'ledger predecessor chain'
function AssertTombstoneContinuity($old,$new,[string]$label){$oldActive=@($old.entries);$oldTomb=@($old.tombstones);$newActive=@($new.entries);$newTomb=@($new.tombstones);$oldTombIds=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($t in $oldTomb){[void]$oldTombIds.Add([string]$t.id)};$newTombIds=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($t in $newTomb){Req(-not(Compare-Object @($t.PSObject.Properties.Name) @('id','old_text_sha256','document','span_start','span_end')))'ledger tombstone exact';Req($newTombIds.Add([string]$t.id)-and@($newActive|? id -ceq $t.id).Count-eq0)"$label tombstone unique";$prior=@($oldActive|? id -ceq $t.id)+@($oldTomb|? id -ceq $t.id);Req($prior.Count-eq1-and$prior[0].text_sha256 -eq $null -or $true)"$label tombstone predecessor";if($prior[0].PSObject.Properties['text_sha256']){Req($prior[0].text_sha256-ceq$t.old_text_sha256-and$prior[0].document-ceq$t.document-and$prior[0].span_start-eq$t.span_start-and$prior[0].span_end-eq$t.span_end)"$label tombstone binding"}else{Req($prior[0].old_text_sha256-ceq$t.old_text_sha256-and$prior[0].document-ceq$t.document-and$prior[0].span_start-eq$t.span_start-and$prior[0].span_end-eq$t.span_end)"$label tombstone carry"}};$removed=@($oldActive|?{$_.id-notin@($newActive.id)});$added=@($newTomb|?{$_.id-notin@($oldTomb.id)});Req($removed.Count-eq$added.Count-and-not(Compare-Object @($removed.id|sort) @($added.id|sort)))"$label tombstone delta"}
AssertTombstoneContinuity $loop27 $loop28 'loop28';AssertTombstoneContinuity $loop28 $ledger 'loop29'
function AssertMigration($name,$old,$new){$meta=$lineage.migrations.$name;$mp=Join-Path $vroot $meta.path;Req((Get-FileHash -Algorithm SHA256 $mp).Hash.ToLowerInvariant()-ceq$meta.sha256)"ledger migration hash $name";$keys=if($name-ceq'loop28'){@('schema','source_ledger_sha256','replacements','tombstones','document_remediations','entries')}else{@('schema','source_ledger_sha256','replacements','tombstones','entries')};$migration=ReadStrictJson $mp $keys "ledger_migration_$name";$oldHash=(Get-FileHash -Algorithm SHA256 (Join-Path $vroot $lineage.anchors.($meta.from).path)).Hash.ToLowerInvariant();Req($migration.schema-ceq'wp5-ledger-text-migration-v1'-and$migration.source_ledger_sha256-ceq$oldHash-and[int]$migration.replacements-eq[int]$meta.replacements-and[int]$migration.tombstones-eq[int]$meta.tombstones-and@($migration.entries).Count-eq([int]$meta.replacements+[int]$meta.tombstones))"ledger migration identity $name";$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($entry in @($migration.entries)){$want=if($entry.disposition-ceq'replacement'){@('id','disposition','old','new_entry','reason')}else{@('id','disposition','old','reason')};Req(-not(Compare-Object @($entry.PSObject.Properties.Name) $want)-and$entry.disposition-in@('replacement','tombstone')-and$seen.Add([string]$entry.id)-and-not[string]::IsNullOrWhiteSpace([string]$entry.reason))"ledger migration exact $name";Req(-not(Compare-Object @($entry.old.PSObject.Properties.Name) @('id','old_text_sha256','document','span_start','span_end')))'ledger migration old exact';$prior=@($old.entries|? id -ceq $entry.id);Req($prior.Count-eq1-and$prior[0].text_sha256-ceq$entry.old.old_text_sha256-and$prior[0].document-ceq$entry.old.document-and$prior[0].span_start-eq$entry.old.span_start-and$prior[0].span_end-eq$entry.old.span_end)"ledger migration old binding $name";if($entry.disposition-ceq'replacement'){$current=@($new.entries|? id -ceq $entry.id);Req($current.Count-eq1-and-not(Compare-Object @($current[0].PSObject.Properties.Name) @($entry.new_entry.PSObject.Properties.Name)))"ledger migration replacement schema $name";if(-not$allowFixtureMigrationBypass){foreach($field in $current[0].PSObject.Properties.Name){Req((($current[0].$field|ConvertTo-Json -Depth 24 -Compress)-ceq($entry.new_entry.$field|ConvertTo-Json -Depth 24 -Compress)))"ledger migration replacement $name/$($entry.id)/$field"}}}else{Req(@($new.entries|? id -ceq $entry.id).Count-eq0-and@($new.tombstones|?{$_.id-ceq$entry.id-and$_.old_text_sha256-ceq$entry.old.old_text_sha256-and$_.document-ceq$entry.old.document-and$_.span_start-eq$entry.old.span_start-and$_.span_end-eq$entry.old.span_end}).Count-eq1)"ledger migration tombstone no revival $name"}};Req(@($migration.entries|? disposition -ceq'replacement').Count-eq[int]$meta.replacements-and@($migration.entries|? disposition -ceq'tombstone').Count-eq[int]$meta.tombstones)"ledger migration disposition $name";if($name-ceq'loop28'){Req(@($migration.document_remediations).Count-eq1)'ledger migration prose count'}}
AssertMigration 'loop28' $loop27 $loop28;AssertMigration 'loop29' $loop28 $ledger
$scopeLineage=ReadStrictJson (Join-Path $vroot 'scope-registry-lineage.json') @('schema','generations') scope_lineage;Req($scopeLineage.schema-ceq'wp5-scope-registry-lineage-v1'-and-not(Compare-Object @($scopeLineage.generations.PSObject.Properties.Name) @('loop28','loop29')))'scope lineage schema';foreach($name in @('loop28','loop29')){$g=$scopeLineage.generations.$name;Req(-not(Compare-Object @($g.PSObject.Properties.Name) @('path','sha256','scope_count','ledger_path','ledger_sha256')))"scope lineage exact $name";$lp=Join-Path $vroot $g.ledger_path;$sp=Join-Path $vroot $g.path;Req((Get-FileHash -Algorithm SHA256 $lp).Hash.ToLowerInvariant()-ceq$g.ledger_sha256-and(Get-FileHash -Algorithm SHA256 $sp).Hash.ToLowerInvariant()-ceq$g.sha256)"scope lineage hash $name";$lr=ReadStrictJson $lp @('schema','previous_ledger_sha256','tombstones','counts','sources','entries') "scope_ledger_$name";$sr=ReadStrictJson $sp @('schema','scopes') "scope_registry_$name";Req($sr.schema-ceq'wp5-scope-registry-v1'-and@($sr.scopes.PSObject.Properties).Count-eq[int]$g.scope_count)'scope lineage registry $name';$used=@($lr.entries.scope|?{$_-match'#'}|sort -Unique);Req(-not(Compare-Object @($sr.scopes.PSObject.Properties.Name) $used))"scope lineage use exact $name"}
'@
$matches = [regex]::Matches($text, $pattern)
if ($matches.Count -ne 1) { throw "Expected exactly one legacy lineage block, found $($matches.Count)." }
$text = [regex]::Replace($text, $pattern, [System.Text.RegularExpressions.MatchEvaluator]{ param($m) $replacement }, 1)
[IO.File]::WriteAllText($ValidatorPath, $text, [Text.UTF8Encoding]::new($false))
Write-Output "PASS upgraded $ValidatorPath"
